def apply_op(op, a, b):
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if op == "/":
        return a / b
    raise ValueError(op)

def evaluate(expr):
    stack = []
    for tok in expr.split():
        print(f"tok={tok}, stack before={stack}")
        if tok in ("+", "-", "*", "/"):
            b = stack.pop()
            a = stack.pop()
            result = apply_op(tok, a, b)
            print(f"  {tok}: a={a}, b={b} -> result={result}")
            stack.append(result)
        else:
            val = float(tok)
            stack.append(val)
    return stack[0]

